class LmdbRemoteValueCaptureTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@ParameterizedTest
	@ValueSource(strings = { "constant", "scalar-var", "stable-values", "mutable-values", "nested-constant" })
	void lexicalCapturePreservesActualRemoteProvenance(String route, @TempDir Path directory) throws Exception {
		try (CountingValues values = new CountingValues(directory.toFile())) {
			RemoteBNode remote = remote();
			Value original = route.equals("nested-constant")
					? VF.createTripleTerm(remote, VF.createIRI("urn:capture:p"), remote)
					: remote;
			ValueConstant constant = new ValueConstant(original);
			TupleExpr root;
			if (route.endsWith("values")) {
				BindingSetAssignment assignment = new BindingSetAssignment();
				assignment.setDeclaredBindingNames(Set.of("value", "optional"));
				MapBindingSet mutable = new MapBindingSet();
				mutable.addBinding("value", original);
				assignment.setBindingSets(route.equals("stable-values")
						? List.of(new ListBindingSet(List.of("value", "optional"), original, null))
						: List.of(mutable));
				root = assignment;
			} else {
				root = new Extension(new SingletonSet(), new ExtensionElem(route.equals("scalar-var")
						? Var.of("input", original)
						: constant, "result"));
			}
			new LmdbValueLookupOptimizer(values).optimize(root, null, EmptyBindingSet.getInstance());
			Value captured = root instanceof BindingSetAssignment assignment
					? assignment.getBindingSets().iterator().next().getValue("value")
					: ((Extension) root).getElements().getFirst().getExpr()instanceof Var variable
							? variable.getValue()
							: constant.getValue();
			assertEquals(0, values.lookups, "lexical capture must not add dictionary membership reads");
			if (captured instanceof TripleTerm triple) {
				assertTrusted(remote, triple.getSubject());
				assertTrusted(remote, triple.getObject());
			} else {
				assertTrusted(remote, captured);
			}
		}
	}

	@ParameterizedTest
	@ValueSource(strings = { "subject", "object", "context" })
	void statementCaptureKeepsOneNativeResolutionAndThePublicProvenance(String position,
			@TempDir Path directory) throws Exception {
		try (CountingValues values = new CountingValues(directory.toFile())) {
			RemoteBNode remote = remote();
			values.startTransaction(true);
			long id = values.storeValue(VF.createBNode(remote.getID()));
			values.commit();
			ValueConstant scalar = new ValueConstant(remote);
			StatementPattern first = pattern(position, remote);
			StatementPattern second = pattern(position, remote);
			BindingSetAssignment assignment = new BindingSetAssignment();
			assignment.setBindingSets(List.of(new ListBindingSet(List.of("shared"), remote)));
			Join root = new Join(new Extension(new SingletonSet(), new ExtensionElem(scalar, "constant")),
					new Join(new Join(first, second), assignment));
			values.lookups = 0;
			new LmdbValueLookupOptimizer(values).optimize(root, null, EmptyBindingSet.getInstance());
			LmdbValueVar captured = assertInstanceOf(LmdbValueVar.class, variable(first, position));
			assertTrue(captured.isLmdbValueResolved(), "actual statement inputs keep native ID specialization");
			assertEquals(id, captured.getLmdbValue().getInternalIdentity().id());
			assertEquals(1, values.lookups, "all same-instance occurrences share one native ID lookup");
			assertSame(scalar.getValue(), captured.getValue());
			assertSame(captured.getValue(), variable(second, position).getValue());
			assertSame(captured.getValue(), assignment.getBindingSets().iterator().next().getValue("shared"));
			assertTrusted(remote, captured.getValue());
			assertTrusted(remote, captured.clone().getValue());
		}
	}

	@Test
	void ordinaryEqualTextCaptureDoesNotAcquireRemoteAuthority(@TempDir Path directory) throws Exception {
		try (CountingValues values = new CountingValues(directory.toFile())) {
			RemoteBNode remote = remote();
			ValueConstant scalar = new ValueConstant(VF.createBNode(remote.getID()));
			new LmdbValueLookupOptimizer(values).optimize(
					new Extension(new SingletonSet(), new ExtensionElem(scalar, "result")), null,
					EmptyBindingSet.getInstance());
			assertEquals(remote, scalar.getValue());
			assertTrue(!(scalar.getValue() instanceof RemoteBNode));
			assertEquals(0, values.lookups);
		}
	}

	@ParameterizedTest
	@ValueSource(strings = { "subject", "object", "context" })
	void actualCompiledStatementKeepsTheSuppliedRemoteValue(String position, @TempDir Path directory) {
		RemoteBNode remote = remote();
		SailRepository repository = new SailRepository(new LmdbStore(directory.toFile()));
		repository.init();
		try (var connection = repository.getConnection()) {
			Resource subject = position.equals("subject") ? VF.createBNode(remote.getID())
					: VF.createIRI("urn:capture:s");
			Value object = position.equals("object") ? VF.createBNode(remote.getID()) : VF.createLiteral("present");
			Resource context = position.equals("context") ? VF.createBNode(remote.getID())
					: VF.createIRI("urn:capture:g");
			connection.add(subject, VF.createIRI("urn:capture:p"), object, context);
			String body = switch (position) {
			case "subject" -> "?input <urn:capture:p> ?hit";
			case "object" -> "?hit <urn:capture:p> ?input";
			default -> "GRAPH ?input { ?hit <urn:capture:p> ?o }";
			};
			var query = connection.prepareTupleQuery("SELECT ?input ?hit WHERE { " + body + " }");
			query.setBinding("input", remote);
			for (int attempt = 0; attempt < 3; attempt++) {
				try (var rows = query.evaluate()) {
					assertTrue(rows.hasNext(), "a stored bound statement must execute the actual native lookup");
					assertTrusted(remote, rows.next().getValue("input"));
					assertTrue(!rows.hasNext());
				}
			}
		} finally {
			repository.shutDown();
		}
	}

	private static StatementPattern pattern(String position, Value remote) {
		return new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS,
				position.equals("subject") ? Var.of("s", remote) : new Var("s"), new Var("p"),
				position.equals("object") ? Var.of("o", remote) : new Var("o"),
				position.equals("context") ? Var.of("g", remote) : new Var("g"));
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void actualNativeVarCaptureAndClonePreserveAllDeclaredTraits(boolean flagged, @TempDir Path directory)
			throws Exception {
		try (CountingValues values = new CountingValues(directory.toFile())) {
			Value value = VF.createBNode("declared-traits");
			values.startTransaction(true);
			long id = values.storeValue(value);
			values.commit();
			Var original = Var.of("input", value, flagged, flagged, flagged);
			original.setVariableScopeChange(flagged);
			StatementPattern root = new StatementPattern(original, new Var("p"), new Var("o"));
			values.lookups = 0;
			new LmdbValueLookupOptimizer(values).optimize(root, null, EmptyBindingSet.getInstance());
			LmdbValueVar captured = assertInstanceOf(LmdbValueVar.class, root.getSubjectVar());
			assertTrue(captured.isLmdbValueResolved());
			assertEquals(id, captured.getLmdbValue().getInternalIdentity().id());
			assertEquals(1, values.lookups);
			LmdbValueVar copy = captured.clone();
			assertAll(() -> assertTraits(original, captured), () -> assertTraits(original, copy),
					() -> assertSame(captured.getLmdbValue(), copy.getLmdbValue()),
					() -> assertSame(captured.getValue(), copy.getValue()));
		}
	}

	private static void assertTraits(Var original, Var captured) {
		assertAll(() -> assertEquals(original.isBNode(), captured.isBNode(), "BNode role"),
				() -> assertEquals(original.isAnonymous(), captured.isAnonymous(), "anonymous role"),
				() -> assertEquals(original.isConstant(), captured.isConstant(), "constant role"),
				() -> assertEquals(original.isVariableScopeChange(), captured.isVariableScopeChange(), "scope change"));
	}

	private static Var variable(StatementPattern pattern, String position) {
		return switch (position) {
		case "subject" -> pattern.getSubjectVar();
		case "object" -> pattern.getObjectVar();
		default -> pattern.getContextVar();
		};
	}

	private static RemoteBNode remote() {
		return (RemoteBNode) RemoteBNode.newResponseScope(new BlankNodeAllocationScope("capture-", id -> false), VF,
				new Object(), true).map(VF.createBNode("original"));
	}

	private static void assertTrusted(RemoteBNode original, Value actual) {
		RemoteBNode copy = assertInstanceOf(RemoteBNode.class, actual);
		assertEquals(original.getID(), copy.getID());
		assertTrue(RemoteBNode.sameTrustedIdentity(original, copy));
	}

	private static final class CountingValues extends ValueStore implements AutoCloseable {
		private int lookups;

		private CountingValues(File directory) throws IOException {
			super(new File(directory, "values"), new LmdbStoreConfig());
		}

		@Override
		public long getId(Value value, boolean create) throws IOException {
			if (!create) {
				lookups++;
			}
			return super.getId(value, create);
		}
	}
}
